'use client';
import React,{useState,useEffect,useMemo} from 'react';
import {Activity,ArrowDownToLine,ArrowRight,ArrowUpRight,BarChart3,Check,ChevronDown,ChevronUp,Clock3,Cloud,Copy,Dumbbell,Flame,Home,Layers,ListPlus,MoreHorizontal,Pause,Play,Plus,RotateCcw,Ruler,Scale,Search,Sparkles,Trash2,X,CheckCircle2,CalendarDays,Pencil,FileText,WifiOff,Timer,MoveUp,MoveDown} from 'lucide-react';
import {ResponsiveContainer,LineChart,Line,XAxis,YAxis,Tooltip,CartesianGrid} from 'recharts';
import {useStore} from '../lib/use-store';
import {CATALOG,MUSCLES,uid,today,normalize,newExercise,parseRoutine,startSession,weekRange,volume,tonnage,csv} from '../lib/fitness';
import type {Routine,Exercise,Session,Measurement,Muscle,RecordData,SetLog,SessionExercise} from '../lib/fitness';
type Tab='home'|'routines'|'workout'|'progress'|'volume';
const NAV=[{id:'home',label:'Inicio',icon:Home},{id:'routines',label:'Rutinas',icon:Dumbbell},{id:'workout',label:'Entrenar',icon:Play},{id:'progress',label:'Progreso',icon:Activity},{id:'volume',label:'Volumen',icon:Layers}] as const;
const TEMPLATE='Día 1: Pecho y espalda\nPress de banca: 3 × 6–8, 100 kg, descanso 2 min\nRemo con barra: 3 × 8–10, descanso 90 s\nJalón al pecho: 3 × 10–12, descanso 90 s\n\nDía 2: Piernas\nSentadilla: 3 × 6–8, descanso 3 min\nPeso muerto rumano: 3 × 8–10, descanso 2 min\nCurl femoral: 3 × 10–12, descanso 90 s';
const fmt=(n:number)=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:1}).format(n);
const displayDate=(d:string)=>new Date(d+'T12:00:00').toLocaleDateString('es-PE',{day:'numeric',month:'short'});
const restLabel=(s:number|null)=>s===null?'Sin definir':s>=60?`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')} min`:`${s} s`;
const download=(name:string,content:string,type='text/plain')=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
function Modal({title,subtitle,children,onClose,wide=false}:{title:string;subtitle?:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){useEffect(()=>{const prev=document.body.style.overflow;document.body.style.overflow='hidden';const escape=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();};document.addEventListener('keydown',escape);return()=>{document.body.style.overflow=prev;document.removeEventListener('keydown',escape);};},[onClose]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section role="dialog" aria-modal="true" aria-label={title} className={'modal '+(wide?'wide':'')}><header className="modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn" aria-label="Cerrar" onClick={onClose}><X size={21}/></button></header>{children}</section></div>;}
function Empty({icon:Icon,title,text,action}:{icon:typeof Dumbbell;title:string;text:string;action?:React.ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={28}/></span><h3>{title}</h3><p>{text}</p>{action}</div>;}
function Metric({icon:Icon,label,value,unit,detail}:{icon:typeof Dumbbell;label:string;value:string;unit?:string;detail:string}){return <div className="metric"><span className="metric-icon"><Icon size={18}/></span><span className="metric-label">{label}</span><div className="metric-value">{value}<small>{unit}</small></div><span className="metric-detail">{detail}</span></div>;}
function Chart({data,field,color}:{data:Measurement[];field:'weight'|'waist';color:string}){const filtered=data.filter(d=>d[field]!==null);if(!filtered.length)return <div className="chart-empty"><div className="chart-grid"/><p>Tu evolución empieza con el primer registro.</p></div>;return <div className="chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={filtered} margin={{top:12,right:12,left:-12,bottom:0}}><CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#ebedf2"/><XAxis dataKey="date" tickFormatter={displayDate} tick={{fill:'#9295a5',fontSize:11}} axisLine={false} tickLine={false} minTickGap={30}/><YAxis domain={['dataMin - 1','dataMax + 1']} tick={{fill:'#9295a5',fontSize:11}} tickFormatter={v=>fmt(v)} axisLine={false} tickLine={false}/><Tooltip labelFormatter={v=>displayDate(String(v))} formatter={v=>[`${fmt(Number(v))} ${field==='weight'?'kg':'cm'}`,field==='weight'?'Peso':'Cintura']} contentStyle={{borderRadius:12,border:'1px solid #e8e8ef'}}/><Line type="linear" dataKey={field} stroke={color} strokeWidth={3} dot={{r:4,strokeWidth:3,fill:'white'}} activeDot={{r:6}}/></LineChart></ResponsiveContainer></div>;}
function MuscleBody({stats,selected,onSelect,back=false}:{stats:ReturnType<typeof volume>;selected:Muscle|null;onSelect:(m:Muscle)=>void;back?:boolean}){
 const max=Math.max(1,...Object.values(stats).map(s=>s.direct));const fill=(m:Muscle)=>stats[m].direct?`hsl(252 75% ${86-stats[m].direct/max*30}%)`:'#e5e7ee';
 function region(m:Muscle,d:string,key?:string){return <path key={key??m} d={d} fill={fill(m)} stroke={selected===m?'#423185':'#f7f8fa'} strokeWidth={selected===m?2.3:1.5} role="button" tabIndex={0} aria-label={`${m}: ${stats[m].direct} series directas`} onClick={()=>onSelect(m)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect(m);}}} style={{cursor:'pointer'}}><title>{m}: {stats[m].direct} series directas</title></path>;}
 return <div className="body-view"><svg viewBox="0 0 180 380" aria-label={back?'Vista posterior':'Vista frontal'}><circle cx="90" cy="28" r="20" fill="#e5e7ee"/><path d="M79 46h22l3 14 23 8 15 17 10 49 9 48-7 20-10-2-2-17-13-42-8-30 1 63 10 44-7 61-3 43-7 34-1 24-22 2-2-10 10-21 3-34-2-46-5-42h-4l-5 42-2 46 3 34 10 21-2 10-22-2-1-24-7-34-3-43-7-61 10-44 1-63-8 30-13 42-2 17-10 2-7-20 9-48 10-49 15-17 23-8z" fill="#e5e7ee"/>
 {region(back?'Hombro posterior':'Hombro anterior','M59 70q-16 7-19 25l15 7 15-23z','shoulderL')}{region(back?'Hombro posterior':'Hombro anterior','M121 70q16 7 19 25l-15 7-15-23z','shoulderR')}
 {region('Hombro lateral','M40 96l-5 21 10 4 9-18z','lateralL')}{region('Hombro lateral','M140 96l5 21-10 4-9-18z','lateralR')}
 {back?<>{region('Espalda','M71 66l18 4v73l-25-17-5-37z','backL')}{region('Espalda','M109 66l-18 4v73l25-17 5-37z','backR')}{region('Espalda','M66 131l23 18v29l-24 5z','backLowL')}{region('Espalda','M114 131l-23 18v29l24 5z','backLowR')}{region('Glúteos','M65 180l24-2v43l-29-5z','gluteL')}{region('Glúteos','M115 180l-24-2v43l29-5z','gluteR')}</>:<>{region('Pecho','M70 66l19 5v38q-17 8-28-6l-1-16z','chestL')}{region('Pecho','M110 66l-19 5v38q17 8 28-6l1-16z','chestR')}{region('Abdominales','M75 115l14-2v66l-18 4-4-37z','absL')}{region('Abdominales','M105 115l-14-2v66l18 4 4-37z','absR')}</>}
 {region(back?'Tríceps':'Bíceps','M45 121l11-12-3 29-8 19-13-5z','armL')}{region(back?'Tríceps':'Bíceps','M135 121l-11-12 3 29 8 19 13-5z','armR')}
 {region(back?'Isquios':'Cuádriceps','M62 222l23 3-6 48-8 15-10-11z','thighL')}{region(back?'Isquios':'Cuádriceps','M118 222l-23 3 6 48 8 15 10-11z','thighR')}
 {region('Pantorrillas','M62 294l15-4 2 21-4 26-9-4z','calfL')}{region('Pantorrillas','M118 294l-15-4-2 21 4 26 9-4z','calfR')}
 </svg><span>{back?'POSTERIOR':'FRONTAL'}</span></div>;
}
function ExerciseEditor({exercise:e,onChange,onRemove,onMove,index,total}:{exercise:Exercise;onChange:(e:Exercise)=>void;onRemove:()=>void;onMove:(dir:number)=>void;index:number;total:number}){const[more,setMore]=useState(!e.primary.length);const[search,setSearch]=useState(false);return <article className="editor-exercise"><div className="exercise-top"><span className="exercise-number">{String(index+1).padStart(2,'0')}</span><div className="exercise-name-input"><input aria-label="Nombre del ejercicio" maxLength={200} value={e.name} placeholder="Busca o escribe un ejercicio" onFocus={()=>setSearch(true)} onChange={ev=>{onChange({...e,name:ev.target.value});setSearch(true);}}/>{search&&<div className="exercise-results">{CATALOG.filter(c=>normalize(c.name).includes(normalize(e.name))).slice(0,7).map(c=><button key={c.name} onClick={()=>{onChange({...e,name:c.name,primary:[...c.primary],secondary:[...c.secondary]});setSearch(false);}}>{c.name}<small>{c.primary.join(' · ')}</small></button>)}<button className="subtle" onClick={()=>setSearch(false)}>Usar nombre escrito</button></div>}</div><button className="icon-btn" title="Subir" disabled={index===0} onClick={()=>onMove(-1)}><MoveUp size={15}/></button><button className="icon-btn" title="Bajar" disabled={index===total-1} onClick={()=>onMove(1)}><MoveDown size={15}/></button><button className="icon-btn danger" aria-label="Eliminar ejercicio" onClick={onRemove}><Trash2 size={17}/></button></div><div className="editor-fields"><label>Series<input type="number" min="1" max="30" value={e.sets} onChange={v=>onChange({...e,sets:Math.min(30,Math.max(1,Math.round(Number(v.target.value))))})}/></label><label>Reps objetivo<input maxLength={40} value={e.reps} placeholder="8–12" onChange={v=>onChange({...e,reps:v.target.value})}/></label><label>Peso · kg<input type="number" min="0" step="0.5" placeholder="Por registrar" value={e.weight??''} onChange={v=>onChange({...e,weight:v.target.value===''?null:Math.min(10000,Math.max(0,Number(v.target.value)))})}/></label><label>Descanso · s<input type="number" min="0" max="3600" placeholder="Sin definir" value={e.rest??''} onChange={v=>onChange({...e,rest:v.target.value===''?null:Math.min(3600,Math.max(0,Math.round(Number(v.target.value))))})}/></label></div><button className={'text-btn '+(!e.primary.length?'warning-text':'')} onClick={()=>setMore(!more)}>{e.primary.length?e.primary.join(' · '):'Asigna los músculos principales'} {more?<ChevronUp size={14}/>:<ChevronDown size={14}/>}</button>{more&&<div className="exercise-details"><span className="field-label">Trabajo directo</span><div className="chips">{MUSCLES.map(m=><button key={m} className={'chip '+(e.primary.includes(m)?'selected':'')} onClick={()=>onChange({...e,primary:e.primary.includes(m)?e.primary.filter(x=>x!==m):[...e.primary,m],secondary:e.secondary.filter(x=>x!==m)})}>{m}</button>)}</div><span className="field-label">Participación secundaria</span><div className="chips">{MUSCLES.filter(m=>!e.primary.includes(m)).map(m=><button key={m} className={'chip '+(e.secondary.includes(m)?'selected':'')} onClick={()=>onChange({...e,secondary:e.secondary.includes(m)?e.secondary.filter(x=>x!==m):[...e.secondary,m]})}>{m}</button>)}</div><label>Notas<input maxLength={4000} value={e.notes} placeholder="Técnica, equipo, indicaciones…" onChange={v=>onChange({...e,notes:v.target.value})}/></label></div>}</article>;}
export default function FitnessApp({userId}:{userId:string}){
 const store=useStore(userId);const[tab,setTab]=useState<Tab>('home');const[toast,setToast]=useState('');const[importOpen,setImportOpen]=useState(false);const[importText,setImportText]=useState('');const[parsed,setParsed]=useState<ReturnType<typeof parseRoutine>|null>(null);const[editor,setEditor]=useState<Routine|null>(null);const[measurement,setMeasurement]=useState<Measurement|null>(null);const[exports,setExports]=useState(false);const[historyEdit,setHistoryEdit]=useState<Session|null>(null);const[exerciseSearch,setExerciseSearch]=useState<string|null>(null);const[range,setRange]=useState('week');const[customFrom,setCustomFrom]=useState(weekRange().from);const[customTo,setCustomTo]=useState(today());const[selectedMuscle,setSelectedMuscle]=useState<Muscle|null>(null);const[now,setNow]=useState(Date.now());const[finishOpen,setFinishOpen]=useState(false);const[chartField,setChartField]=useState<'weight'|'waist'>('weight');const[selectedExercise,setSelectedExercise]=useState('');const[summaryOpen,setSummaryOpen]=useState(false);
 const routines=store.records.filter(r=>r.kind==='routine').map(r=>r.body as Routine);
 const sessions=store.records.filter(r=>r.kind==='session').map(r=>r.body as Session).sort((a,b)=>b.startedAt-a.startedAt);
 const finished=sessions.filter(s=>s.status==='finished');const active=sessions.find(s=>s.status==='active');const workout=historyEdit?sessions.find(s=>s.id===historyEdit.id)??historyEdit:active;
 const measures=store.records.filter(r=>r.kind==='measurement').map(r=>r.body as Measurement).sort((a,b)=>a.date.localeCompare(b.date));
 const latestWeight=[...measures].reverse().find(m=>m.weight!==null);const latestWaist=[...measures].reverse().find(m=>m.waist!==null);
 const wr=weekRange(range==='last'?-1:0);const from=range==='custom'?customFrom:range==='all'?'0000-01-01':wr.from;const to=range==='custom'?customTo:range==='all'?'9999-12-31':wr.to;
 const period=finished.filter(s=>s.date>=from&&s.date<=to);const stats=volume(period);const thisWeek=finished.filter(s=>s.date>=weekRange().from&&s.date<=weekRange().to);const completed=workout?.exercises.reduce((a,e)=>a+e.sets.filter(s=>s.done).length,0)??0;const total=workout?.exercises.reduce((a,e)=>a+e.sets.length,0)??0;const seconds=workout?.timerEnd?Math.max(0,Math.ceil((workout.timerEnd-now)/1000)):0;
 useEffect(()=>{const t=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(t);},[]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t);},[toast]);
 useEffect(()=>{if(active?.timerEnd&&now>=active.timerEnd){store.put('session',{...active,timerEnd:null});setToast('Descanso terminado. Vamos con la siguiente serie.');try{navigator.vibrate?.([150,80,150]);}catch{}}},[now,active?.timerEnd]);
 function notify(s:string){setToast(s);}
 function start(r:Routine){if(active){setTab('workout');notify('Tienes una sesión en curso. Termínala antes de empezar otra.');return;}store.put('session',startSession(r,finished));setHistoryEdit(null);setTab('workout');}
 function editWorkout(s:Session){store.put('session',s);if(historyEdit)setHistoryEdit(s);}
 function patchSet(eId:string,id:string,patch:Partial<SetLog>){if(!workout)return;editWorkout({...workout,exercises:workout.exercises.map(e=>e.id===eId?{...e,sets:e.sets.map(s=>s.id===id?{...s,...patch}:s)}:e)});}
 function completeSet(e:SessionExercise,set:SetLog){if(!workout)return;if(!set.done&&(set.reps===null||set.reps<1||set.weight===null||set.weight<0)){notify('Ingresa peso y repeticiones. Usa 0 kg para peso corporal.');return;}editWorkout({...workout,timerEnd:historyEdit?null:!set.done&&e.rest?Date.now()+e.rest*1000:workout.timerEnd,exercises:workout.exercises.map(x=>x.id===e.id?{...x,sets:x.sets.map(s=>s.id===set.id?{...s,done:!s.done}:s)}:x)});}
 function removeRecord(kind:RecordData['kind'],body:Routine|Session|Measurement){if(confirm('¿Eliminar este registro? Esta acción se sincronizará con tus dispositivos.')){store.put(kind,body,true);notify('Registro eliminado');}}
 function saveRoutine(r:Routine){if(!r.name.trim()||!r.exercises.length){notify('Pon un nombre y agrega al menos un ejercicio.');return false;}if(r.exercises.some(e=>!e.name.trim()||e.sets<1||e.sets>30||!e.primary.length||(e.rest!==null&&(e.rest<0||e.rest>3600))||(e.weight!==null&&e.weight<0))){notify('Revisa nombres, series y músculos principales de cada ejercicio.');return false;}store.put('routine',r);return true;}
 function addMeasure(){setMeasurement({id:uid(),date:today(),weight:null,waist:null});}
 function saveMeasure(){if(!measurement)return;if(!measurement.date||(measurement.weight===null&&measurement.waist===null)){notify('Ingresa peso o cintura y una fecha.');return;}if((measurement.weight!==null&&(measurement.weight<20||measurement.weight>500))||(measurement.waist!==null&&(measurement.waist<20||measurement.waist>300))){notify('Revisa las medidas ingresadas.');return;}const sameDay=measures.find(m=>m.date===measurement.date&&m.id!==measurement.id);if(sameDay){store.put('measurement',{...measurement,id:sameDay.id,weight:measurement.weight??sameDay.weight,waist:measurement.waist??sameDay.waist});if(measures.some(m=>m.id===measurement.id))store.put('measurement',measurement,true);}else store.put('measurement',measurement);setMeasurement(null);notify(sameDay?'Medidas del día actualizadas':'Medidas guardadas');}
 function move(r:Routine,index:number,dir:number){const ex=[...r.exercises];[ex[index],ex[index+dir]]=[ex[index+dir],ex[index]];return {...r,exercises:ex};}
 function exportTraining(){download('fit-z-entrenamientos-'+today()+'.csv',csv([['fecha','sesion_id','rutina','ejercicio','serie','peso_kg','repeticiones','calentamiento','completada','musculos_directos','musculos_secundarios','descanso_s'],...finished.flatMap(s=>s.exercises.flatMap(e=>e.sets.map((x,i)=>[s.date,s.id,s.name,e.name,i+1,x.weight,x.reps,x.warmup?'sí':'no',x.done?'sí':'no',e.primary.join(';'),e.secondary.join(';'),e.rest])))]),'text/csv;charset=utf-8');}
 function exportMeasures(){download('fit-z-medidas-'+today()+'.csv',csv([['fecha','peso_kg','cintura_cm'],...measures.map(m=>[m.date,m.weight,m.waist])]),'text/csv;charset=utf-8');}
 function exportVolume(){download('fit-z-volumen-'+today()+'.csv',csv([['desde','hasta','musculo','series_directas','series_secundarias'],...MUSCLES.map(m=>[from,to,m,stats[m].direct,stats[m].secondary])]),'text/csv;charset=utf-8');}
 async function restoreBackup(file:File){
  if(file.size>10_000_000){notify('El respaldo supera el límite de 10 MB.');return;}
  try{
   const data=JSON.parse(await file.text()) as {app?:string;records?:RecordData[]};
   const records=Array.isArray(data.records)?data.records:[];
   const valid=records.filter(r=>r&&typeof r.id==='string'&&['routine','session','measurement'].includes(r.kind)&&r.body&&typeof r.body==='object'&&'id' in r.body&&r.body.id===r.id&&!r.deleted);
   if(data.app!=='fit-z'||!valid.length){notify('Este archivo no es un respaldo válido de Fit Z.');return;}
   if(!confirm(`Se importarán ${valid.length} registros. Los identificadores repetidos se actualizarán. ¿Continuar?`))return;
   valid.forEach(r=>store.put(r.kind,r.body));
   setExports(false);notify(`${valid.length} registros importados. Se están sincronizando.`);
  }catch{notify('No se pudo leer el respaldo JSON.');}
 }
 const summary=['FIT Z · RESUMEN DE PROGRESO',`Período: ${from} a ${to}`,`Último peso registrado: ${latestWeight?.weight??'sin datos'} kg (${latestWeight?.date??'—'})`,`Última cintura registrada: ${latestWaist?.waist??'sin datos'} cm (${latestWaist?.date??'—'})`,`Entrenamientos completados en el período: ${period.length}`,'','VOLUMEN POR MÚSCULO (series de trabajo completadas)',...MUSCLES.map(m=>`${m}: ${stats[m].direct} directas / ${stats[m].secondary} secundarias`),'','SESIONES',...period.map(s=>`${s.date} · ${s.name}\n${s.exercises.map(e=>`${e.name}: ${e.sets.filter(x=>x.done&&!x.warmup).map(x=>`${x.weight} kg × ${x.reps}`).join(' / ')||'sin series de trabajo completadas'}`).join('\n')}`),'','MEDIDAS',...measures.filter(m=>m.date>=from&&m.date<=to).map(m=>`${m.date}: peso ${m.weight??'—'} kg / cintura ${m.waist??'—'} cm`)].join('\n');
 const exerciseNames=[...new Set(finished.flatMap(s=>s.exercises.map(e=>e.name)))].sort();const exerciseHistory=[...finished].reverse().flatMap(s=>s.exercises.filter(e=>e.name===(selectedExercise||exerciseNames[0])).map(e=>({date:s.date,weight:e.sets.filter(x=>x.done&&!x.warmup&&x.weight!==null).length?Math.max(...e.sets.filter(x=>x.done&&!x.warmup).map(x=>x.weight??0)):null,waist:null,id:s.id})));
 const chartMeasures=measures.filter(m=>m.date>=from&&m.date<=to);
 if(!store.loaded)return <div className="loading"><span className="brand-mark">Z</span><h2>Preparando tu espacio</h2><p>Un momento, vamos a entrenar.</p></div>;
 return <div className="app-shell"><aside className="sidebar"><a className="brand" href="#" onClick={e=>{e.preventDefault();setTab('home');}}><span className="brand-mark">Z</span><span>fit<span className="brand-z">z</span><small>TRAINING JOURNAL</small></span></a><span className="nav-caption">TU ESPACIO</span><nav>{NAV.map(n=><button key={n.id} className={tab===n.id?'nav-item active':'nav-item'} onClick={()=>{setTab(n.id);if(n.id!=='workout')setHistoryEdit(null);}}><n.icon size={20}/><span>{n.label}</span>{n.id==='workout'&&active&&<i/>}</button>)}</nav><div className="sidebar-bottom"><div className="version-card"><span className="mini-z">Z</span><div><b>Un registro a la vez.</b><p>La constancia deja huella.</p></div></div><button className="nav-item" onClick={()=>setExports(true)}><ArrowDownToLine size={19}/><span>Exportar datos</span></button><div className="profile"><span>J</span><div><b>Mi espacio personal</b><small>Fit Z · versión 0.1</small></div></div></div></aside>
 <div className="workspace"><header className="topbar"><span className="topbar-section">Mi entrenamiento <span>/</span> {NAV.find(n=>n.id===tab)?.label}</span><div className="topbar-actions"><button className={'sync-status '+(store.pendingCount?'pending':'')} onClick={()=>void store.sync()} title={store.status}>{store.status.includes('Sin conexión')?<WifiOff size={14}/>:<Cloud size={14}/>}<span>{store.status==='Sincronizado'?'Sincronizado':store.pendingCount?`${store.pendingCount} cambios pendientes`:store.status}</span></button><span className="date-label"><CalendarDays size={15}/>{new Date(today()+'T12:00:00').toLocaleDateString('es-PE',{day:'numeric',month:'long'})}</span></div></header>
 <main className="main-content">
 {tab==='home'&&<><div className="page-heading"><div><div className="eyebrow">TU PROGRESO EMPIEZA AQUÍ</div><h1>Vamos a por más<span className="purple">.</span></h1><p>Entrena con intención. Mira cómo avanzas.</p></div><button className="btn primary" onClick={()=>active?setTab('workout'):setTab('routines')}><Play size={17} fill="currentColor"/>{active?'Retomar entrenamiento':'Empezar a entrenar'}</button></div>
 <div className="metrics-grid"><Metric icon={Scale} label="Peso actual" value={latestWeight?fmt(latestWeight.weight!):'—'} unit="kg" detail={latestWeight?`Registrado el ${displayDate(latestWeight.date)}`:'Agrega tu primer registro'}/><Metric icon={Ruler} label="Cintura" value={latestWaist?fmt(latestWaist.waist!):'—'} unit="cm" detail={latestWaist?`Registrada el ${displayDate(latestWaist.date)}`:'Una medida, una referencia'}/><Metric icon={Dumbbell} label="Entrenamientos" value={String(thisWeek.length)} detail="Completados esta semana"/><Metric icon={Layers} label="Series de trabajo" value={String(thisWeek.reduce((a,s)=>a+s.exercises.reduce((b,e)=>b+e.sets.filter(x=>x.done&&!x.warmup).length,0),0))} detail="Completadas esta semana"/></div>
 <div className="dashboard-grid"><section className="panel progress-panel"><div className="panel-heading"><div><h2>Tu evolución</h2><p>Pequeños registros. Una perspectiva más clara.</p></div><div className="segmented"><button className={chartField==='weight'?'selected':''} onClick={()=>setChartField('weight')}>Peso</button><button className={chartField==='waist'?'selected':''} onClick={()=>setChartField('waist')}>Cintura</button></div></div><Chart data={measures} field={chartField} color={chartField==='weight'?'#7961ee':'#45a38e'}/><div className="panel-footer"><span>{measures.length} registros guardados</span><button className="text-btn" onClick={addMeasure}><Plus size={16}/> Registrar medidas</button></div></section><section className="import-card"><span className="label-light"><Sparkles size={15}/> MENOS CARGA MANUAL</span><h2>Del texto<br/>al entrenamiento.</h2><p>Pega tu rutina. Revisa los detalles.<br/>Empieza con todo listo.</p><div className="mini-sheet"><div><span>Press de banca</span><b>3 × 6–8</b></div><div><span>Remo con barra</span><b>3 × 8–10</b></div><div><span>Jalón al pecho</span><b>3 × 10–12</b></div></div><button className="btn light" onClick={()=>{setImportOpen(true);setParsed(null);}}><FileText size={17}/> Importar rutina <ArrowUpRight size={17}/></button></section></div>
 <div className="dashboard-grid lower"><section className="panel"><div className="panel-heading"><div><h2>Mis rutinas <span className="count">{routines.length}</span></h2><p>Tu siguiente entrenamiento está aquí.</p></div><button className="text-btn" onClick={()=>setTab('routines')}>Ver todas <ArrowRight size={16}/></button></div>{routines.length?<div className="routine-list">{routines.slice(0,3).map(r=><div className="routine-row" key={r.id}><span className="routine-icon"><Dumbbell size={21}/></span><div><b>{r.name}</b><small>{r.exercises.length} ejercicios · {r.exercises.reduce((a,e)=>a+e.sets,0)} series</small></div><button className="icon-btn play-btn" aria-label={`Empezar ${r.name}`} onClick={()=>start(r)}><Play size={18}/></button></div>)}</div>:<Empty icon={Dumbbell} title="Tu primera rutina te espera" text="Créala desde cero o importa el texto de tu plan." action={<button className="btn secondary" onClick={()=>setEditor({id:uid(),name:'Mi rutina',exercises:[newExercise()]})}><Plus size={16}/> Crear rutina</button>}/>}</section><section className="panel recent-panel"><div className="panel-heading"><div><h2>Última sesión</h2><p>Lo que hiciste, siempre a mano.</p></div><Clock3 size={19} className="muted"/></div>{finished[0]?<><div className="last-session"><span className="badge">{displayDate(finished[0].date)}</span><h3>{finished[0].name}</h3><p>{finished[0].exercises.length} ejercicios · {fmt(tonnage(finished[0]))} kg acumulados</p></div><button className="text-btn" onClick={()=>{setHistoryEdit(finished[0]);setTab('workout');}}>Ver entrenamiento <ArrowRight size={16}/></button></>:<Empty icon={Clock3} title="Cada sesión cuenta" text="Tu historial aparecerá al completar tu primer entrenamiento."/>}</section></div></>}
 {tab==='routines'&&<><div className="page-heading"><div><div className="eyebrow">PLANIFICA PARA AVANZAR</div><h1>Mis rutinas<span className="purple">.</span></h1><p>Tu plan, listo para entrar al gimnasio.</p></div><div className="heading-buttons"><button className="btn secondary" onClick={()=>{setImportOpen(true);setParsed(null);}}><FileText size={17}/> Importar texto</button><button className="btn primary" onClick={()=>setEditor({id:uid(),name:'Mi rutina',exercises:[newExercise()]})}><Plus size={17}/> Nueva rutina</button></div></div>{routines.length?<div className="routine-grid">{routines.map((r,i)=><article className="panel routine-card" key={r.id}><div className="routine-card-top"><span className="routine-icon"><Dumbbell size={24}/></span><span className="routine-index">RUTINA {String(i+1).padStart(2,'0')}</span></div><h2>{r.name}</h2><p>{r.exercises.length} ejercicios · {r.exercises.reduce((a,e)=>a+e.sets,0)} series</p><div className="routine-preview">{r.exercises.slice(0,4).map(e=><div key={e.id}><span>{e.name}</span><b>{e.sets} × {e.reps||'—'}</b></div>)}{r.exercises.length>4&&<small>+ {r.exercises.length-4} ejercicios más</small>}</div><div className="routine-muscles">{[...new Set(r.exercises.flatMap(e=>e.primary))].slice(0,4).map(m=><span className="badge" key={m}>{m}</span>)}</div><button className="btn primary full" onClick={()=>start(r)}><Play size={16}/> Empezar entrenamiento</button><div className="card-tools"><button className="text-btn" onClick={()=>setEditor(structuredClone(r))}><Pencil size={14}/> Editar</button><button className="icon-btn" title="Duplicar rutina" onClick={()=>{const copy={...structuredClone(r),id:uid(),name:r.name+' · copia'};store.put('routine',copy);notify('Rutina duplicada');}}><Copy size={16}/></button><button className="icon-btn danger" aria-label="Eliminar rutina" onClick={()=>removeRecord('routine',r)}><Trash2 size={16}/></button></div></article>)}</div>:<section className="panel"><Empty icon={ListPlus} title="Arma tu primera rutina" text="Pega un plan desde ChatGPT o agrega tus ejercicios favoritos." action={<button className="btn primary" onClick={()=>{setImportOpen(true);setParsed(null);}}>Importar desde texto <ArrowRight size={16}/></button>}/></section>}</>}
 {tab==='workout'&&<><div className="page-heading"><div><div className="eyebrow">{historyEdit?'HISTORIAL DE ENTRENAMIENTO':'UN PASO, UNA SERIE'}</div><h1>{workout?.name??'A entrenar'}<span className="purple">.</span></h1><p>{workout?`${displayDate(workout.date)} · ${workout.exercises.length} ejercicios · ${completed}/${total} series completadas`:'Elige una rutina y empieza tu sesión.'}</p></div>{workout&&<div className="heading-buttons">{historyEdit?<><button className="btn secondary" onClick={()=>{setHistoryEdit(null);setTab('progress');}}>Volver al historial</button><button className="icon-btn danger" aria-label="Eliminar sesión" onClick={()=>{removeRecord('session',workout);setHistoryEdit(null);setTab('progress');}}><Trash2 size={19}/></button></>:<button className="btn primary" onClick={()=>setFinishOpen(true)}><CheckCircle2 size={17}/> Terminar sesión</button>}</div>}</div>
 {workout?<><div className="session-strip"><span><Clock3 size={17}/>{historyEdit?`${Math.round(((workout.endedAt??workout.startedAt)-workout.startedAt)/60000)} min`:`${Math.floor((now-workout.startedAt)/60000)} min en curso`}</span><div className="session-progress"><i style={{width:`${total?completed/total*100:0}%`}}/></div><span>{completed} / {total} series</span></div><div className="workout-layout"><div className="exercise-stack">{workout.exercises.map((e,ei)=>{const previous=finished.filter(s=>s.id!==workout.id&&s.startedAt<workout.startedAt).flatMap(s=>s.exercises).find(x=>normalize(x.name)===normalize(e.name));return <section className="panel workout-exercise" key={e.id}><div className="exercise-top"><span className="exercise-number">{String(ei+1).padStart(2,'0')}</span><div className="grow"><h2>{e.name}</h2><span className="exercise-meta">{e.primary.join(' · ')||'Músculos sin asignar'} · Objetivo: {e.reps||'libre'} reps</span></div><button className="icon-btn danger" aria-label="Quitar ejercicio de sesión" onClick={()=>{if(confirm('¿Quitar este ejercicio de la sesión?'))editWorkout({...workout,exercises:workout.exercises.filter(x=>x.id!==e.id)});}}><Trash2 size={16}/></button></div><div className="workout-rest"><Clock3 size={14}/><span>Descanso</span><input aria-label={`Descanso de ${e.name} en segundos`} type="number" min="0" max="3600" value={e.rest??''} placeholder="—" onChange={v=>editWorkout({...workout,exercises:workout.exercises.map(x=>x.id===e.id?{...x,rest:v.target.value===''?null:Math.max(0,Math.min(3600,Math.round(Number(v.target.value))))}:x)})}/><span>s</span>{e.notes&&<span className="exercise-note">{e.notes}</span>}</div><div className="set-grid set-head"><span>SERIE</span><span>ANTERIOR</span><span>KG</span><span>REPS</span><span>✓</span><span/></div>{e.sets.map((s,i)=><div className={'set-grid '+(s.done?'set-done':'')} key={s.id}><button title="Cambiar entre calentamiento y serie de trabajo" className={'set-type '+(s.warmup?'warmup':'')} onClick={()=>patchSet(e.id,s.id,{warmup:!s.warmup})}>{s.warmup?'C':e.sets.slice(0,i+1).filter(x=>!x.warmup).length}</button><span className="previous">{previous?.sets.filter(x=>!x.warmup&&x.done)[e.sets.slice(0,i).filter(x=>!x.warmup).length]&&!s.warmup?`${previous.sets.filter(x=>!x.warmup&&x.done)[e.sets.slice(0,i).filter(x=>!x.warmup).length].weight??'—'} × ${previous.sets.filter(x=>!x.warmup&&x.done)[e.sets.slice(0,i).filter(x=>!x.warmup).length].reps??'—'}`:'—'}</span><input aria-label={`${e.name} serie ${i+1} peso kg`} type="number" inputMode="decimal" min="0" max="10000" step="0.5" placeholder="—" value={s.weight??''} onChange={v=>patchSet(e.id,s.id,{weight:v.target.value===''?null:Math.min(10000,Math.max(0,Number(v.target.value))),done:false})}/><input aria-label={`${e.name} serie ${i+1} repeticiones`} type="number" inputMode="numeric" min="1" max="1000" placeholder={e.reps} value={s.reps??''} onChange={v=>patchSet(e.id,s.id,{reps:v.target.value===''?null:Math.min(1000,Math.max(0,Math.round(Number(v.target.value)))),done:false})}/><button className={'complete-btn '+(s.done?'checked':'')} aria-label={s.done?'Desmarcar serie':'Completar serie'} onClick={()=>completeSet(e,s)}><Check size={19}/></button><button className="icon-btn delete-set" aria-label="Eliminar serie" onClick={()=>{if(s.done&&!confirm('¿Eliminar esta serie completada?'))return;editWorkout({...workout,exercises:workout.exercises.map(x=>x.id===e.id?{...x,sets:x.sets.filter(y=>y.id!==s.id)}:x)});}}><X size={14}/></button></div>)}<button className="add-set" onClick={()=>editWorkout({...workout,exercises:workout.exercises.map(x=>x.id===e.id?{...x,sets:[...x.sets,{id:uid(),weight:x.sets.at(-1)?.weight??null,reps:null,done:false,warmup:false}]}:x)})}><Plus size={16}/> Agregar serie</button></section>;})}<button className="btn secondary full" onClick={()=>setExerciseSearch('')}><Plus size={18}/> Agregar ejercicio a la sesión</button><label className="session-notes">Notas de la sesión<textarea maxLength={4000} value={workout.notes} placeholder="¿Cómo te sentiste? ¿Cambiaste algún ejercicio?" onChange={e=>editWorkout({...workout,notes:e.target.value})}/></label>{historyEdit&&<label className="history-date">Fecha de la sesión<input type="date" value={workout.date} onChange={e=>{if(e.target.value)editWorkout({...workout,date:e.target.value});}}/></label>}</div><aside className="workout-aside"><section className="timer-card"><span className="eyebrow"><Timer size={16}/> TU DESCANSO</span><div className="timer-digits">{`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}</div><p>{seconds?'Respira. La siguiente serie te espera.':'Se inicia al completar una serie.'}</p>{!historyEdit&&<><div className="timer-tools"><button className="btn secondary" onClick={()=>editWorkout({...workout,timerEnd:Date.now()+(seconds+30)*1000})}>+30 s</button><button className="btn secondary" disabled={!seconds} onClick={()=>editWorkout({...workout,timerEnd:null})}>Omitir</button></div><button className="text-btn" onClick={()=>editWorkout({...workout,timerEnd:Date.now()+90000})}><Play size={14}/> Iniciar 90 s</button></>}</section><div className="session-tip"><span className="tip-icon"><Flame size={19}/></span><h3>Solo tú contra tu anterior versión.</h3><p>Usa la columna «Anterior» como referencia para tu próxima serie.</p><small>Toca el número de serie para marcarla como calentamiento (C).</small><small>Usa 0 kg en ejercicios de peso corporal. En mancuernas, mantén siempre el mismo criterio de peso.</small></div>{!historyEdit&&<button className="text-btn danger" onClick={()=>{if(confirm('¿Descartar esta sesión en curso?')){store.put('session',workout,true);setTab('home');}}}>Descartar sesión</button>}</aside></div></>:<section className="panel"><Empty icon={Play} title="Todo empieza con una serie" text="Elige una rutina guardada para empezar a registrar tu entrenamiento." action={<button className="btn primary" onClick={()=>setTab('routines')}>Elegir rutina <ArrowRight size={16}/></button>}/></section>}</>}
 {tab==='progress'&&<><div className="page-heading"><div><div className="eyebrow">LOS DATOS CUENTAN TU HISTORIA</div><h1>Tu progreso<span className="purple">.</span></h1><p>Medidas, rendimiento e historial en un mismo lugar.</p></div><button className="btn primary" onClick={addMeasure}><Plus size={18}/> Registrar medidas</button></div><div className="filter-bar"><span><CalendarDays size={17}/> Período</span><select aria-label="Período del progreso" value={range} onChange={e=>setRange(e.target.value)}><option value="week">Esta semana</option><option value="last">Semana anterior</option><option value="all">Todo el historial</option><option value="custom">Personalizado</option></select>{range==='custom'&&<><input aria-label="Desde" type="date" value={customFrom} onChange={e=>setCustomFrom(e.target.value)}/><span>a</span><input aria-label="Hasta" type="date" value={customTo} onChange={e=>setCustomTo(e.target.value)}/></>}</div><div className="two-col"><section className="panel"><div className="panel-heading"><div><h2>Peso corporal</h2><p>{latestWeight?`${fmt(latestWeight.weight!)} kg · último registro`:'Tu punto de partida'}</p></div><Scale size={20} className="purple"/></div><Chart data={chartMeasures} field="weight" color="#7961ee"/><div className="panel-footer"><span>{chartMeasures.filter(m=>m.weight!==null).length} registros en el período</span><b>{(()=>{const week=measures.filter(m=>m.date>=weekRange().from&&m.date<=weekRange().to&&m.weight!==null);return week.length?`Media semanal: ${fmt(week.reduce((a,m)=>a+m.weight!,0)/week.length)} kg`:'Sin media esta semana';})()}</b></div></section><section className="panel"><div className="panel-heading"><div><h2>Cintura</h2><p>{latestWaist?`${fmt(latestWaist.waist!)} cm · último registro`:'Una referencia para comparar'}</p></div><Ruler size={20} color="#45a38e"/></div><Chart data={chartMeasures} field="waist" color="#45a38e"/><div className="panel-footer"><span>Mide en condiciones similares.</span><b>{(()=>{const first=measures.find(m=>m.waist!==null);return first&&latestWaist&&first.id!==latestWaist.id?`${latestWaist.waist!-first.waist!>0?'+':''}${fmt(latestWaist.waist!-first.waist!)} cm desde el inicio`:'—';})()}</b></div></section></div><section className="panel spaced"><div className="panel-heading"><div><h2>Rendimiento por ejercicio</h2><p>Mayor peso registrado por sesión, en series de trabajo completadas.</p></div>{exerciseNames.length>0&&<select aria-label="Ejercicio para analizar" value={selectedExercise||exerciseNames[0]} onChange={e=>setSelectedExercise(e.target.value)}>{exerciseNames.map(n=><option key={n}>{n}</option>)}</select>}</div>{exerciseNames.length?<Chart data={exerciseHistory.filter(m=>m.date>=from&&m.date<=to)} field="weight" color="#7961ee"/>:<Empty icon={BarChart3} title="Tu rendimiento, en perspectiva" text="Completa una sesión para empezar a comparar tus ejercicios."/>}</section><div className="two-col spaced"><section className="panel"><div className="panel-heading"><div><h2>Registro de medidas</h2><p>{chartMeasures.length} registros en el período seleccionado.</p></div><button className="icon-btn" aria-label="Exportar medidas" onClick={exportMeasures}><ArrowDownToLine size={18}/></button></div>{chartMeasures.length?<div className="data-table-wrap"><table className="data-table"><thead><tr><th>Fecha</th><th>Peso</th><th>Cintura</th><th/></tr></thead><tbody>{[...chartMeasures].reverse().map(m=><tr key={m.id}><td>{displayDate(m.date)}</td><td>{m.weight!==null?fmt(m.weight)+' kg':'—'}</td><td>{m.waist!==null?fmt(m.waist)+' cm':'—'}</td><td className="table-tools"><button className="icon-btn" aria-label="Editar medida" onClick={()=>setMeasurement({...m})}><Pencil size={14}/></button><button className="icon-btn danger" aria-label="Eliminar medida" onClick={()=>removeRecord('measurement',m)}><Trash2 size={14}/></button></td></tr>)}</tbody></table></div>:<Empty icon={Ruler} title="Registra tu punto de partida" text="Puedes guardar peso, cintura o ambos."/>}</section><section className="panel"><div className="panel-heading"><div><h2>Historial de sesiones</h2><p>{period.length} entrenamientos en el período.</p></div><Clock3 size={18} className="muted"/></div>{period.length?<div className="routine-list">{period.map(s=><button className="routine-row history-row" key={s.id} onClick={()=>{setHistoryEdit(s);setTab('workout');}}><span className="routine-icon"><CheckCircle2 size={20}/></span><div><b>{s.name}</b><small>{displayDate(s.date)} · {s.exercises.reduce((a,e)=>a+e.sets.filter(x=>x.done&&!x.warmup).length,0)} series de trabajo</small></div><ArrowUpRight size={17}/></button>)}</div>:<Empty icon={Clock3} title="Tu historial empieza aquí" text="Las sesiones completadas se guardarán en esta lista."/>}</section></div></>}
 {tab==='volume'&&<><div className="page-heading"><div><div className="eyebrow">ENTIENDE CÓMO REPARTES TU TRABAJO</div><h1>Volumen muscular<span className="purple">.</span></h1><p>Series completadas por músculo. Calentamientos excluidos.</p></div><button className="btn secondary" onClick={exportVolume}><ArrowDownToLine size={17}/> Exportar volumen</button></div><div className="filter-bar"><span><CalendarDays size={17}/> Período</span><select aria-label="Período de volumen" value={range} onChange={e=>setRange(e.target.value)}><option value="week">Esta semana</option><option value="last">Semana anterior</option><option value="all">Todo el historial</option><option value="custom">Personalizado</option></select>{range==='custom'&&<><input aria-label="Desde" type="date" value={customFrom} onChange={e=>setCustomFrom(e.target.value)}/><span>a</span><input aria-label="Hasta" type="date" value={customTo} onChange={e=>setCustomTo(e.target.value)}/></>}<span className="filter-info">{period.length} sesiones completadas</span></div><div className="volume-layout"><section className="panel anatomy-panel"><div className="panel-heading"><div><h2>Tu mapa de entrenamiento</h2><p>Toca un músculo para ver el detalle.</p></div></div><div className="body-pair"><MuscleBody stats={stats} selected={selectedMuscle} onSelect={setSelectedMuscle}/><MuscleBody stats={stats} selected={selectedMuscle} onSelect={setSelectedMuscle} back/></div><div className="heat-legend"><span>0 series</span><i/><span>Más series directas</span></div><p className="anatomy-caption">El color muestra cantidad relativa de series en el período, no suficiencia ni recuperación.</p></section><section className="panel volume-table-panel"><div className="panel-heading"><div><h2>Series por músculo</h2><p>Trabajo directo y participación secundaria.</p></div></div><div className="volume-table"><div className="volume-head"><span>MÚSCULO</span><span>DIRECTAS</span><span>SECUND.</span></div>{MUSCLES.map(m=><button key={m} className={'volume-row '+(selectedMuscle===m?'selected':'')} onClick={()=>setSelectedMuscle(m)}><div><span>{m}</span><div className="muscle-bar"><i style={{width:`${stats[m].direct/Math.max(1,...Object.values(stats).map(s=>s.direct))*100}%`}}/></div></div><b>{stats[m].direct}</b><span>{stats[m].secondary}</span></button>)}</div><div className="volume-note">Una serie puede trabajar directamente varios músculos. Las columnas se muestran separadas; no se suman como series equivalentes.</div></section></div>{selectedMuscle&&<section className="panel muscle-detail spaced"><div className="panel-heading"><div><h2>{selectedMuscle}</h2><p>{stats[selectedMuscle].direct} series directas · {stats[selectedMuscle].secondary} secundarias</p></div><button className="icon-btn" aria-label="Cerrar detalle" onClick={()=>setSelectedMuscle(null)}><X size={18}/></button></div>{stats[selectedMuscle].exercises.size?<div className="chips">{Array.from(stats[selectedMuscle].exercises).map(e=><span className="badge" key={e}>{e}</span>)}</div>:<p className="muted">Sin series completadas para este músculo en el período.</p>}</section>}</>}
 <footer className="main-footer"><span>FIT Z <b>0.1</b></span><span>Entrena. Registra. Evoluciona.</span><button onClick={()=>setExports(true)}>Tus datos, contigo <ArrowUpRight size={12}/></button></footer>
 </main></div>
 <nav className="mobile-nav">{NAV.map(n=><button key={n.id} className={tab===n.id?'active':''} onClick={()=>{setTab(n.id);if(n.id!=='workout')setHistoryEdit(null);}}><n.icon size={21}/><span>{n.label}</span>{n.id==='workout'&&active&&<i/>}</button>)}</nav>
 {active&&tab!=='workout'&&<button className="active-session-banner" onClick={()=>{setHistoryEdit(null);setTab('workout');}}><span className="pulsing"/><b>Sesión en curso</b><span>{active.name}</span><ArrowRight size={17}/></button>}
 {tab==='workout'&&seconds>0&&<button className="mobile-timer" onClick={()=>workout&&editWorkout({...workout,timerEnd:null})}><Timer size={17}/><b>{Math.floor(seconds/60)}:{String(seconds%60).padStart(2,'0')}</b><span>Omitir descanso</span></button>}
 {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}</div>}
 {measurement&&<Modal title={measures.some(m=>m.id===measurement.id)?'Editar medidas':'Registrar medidas'} subtitle="Un registro rápido para seguir tu evolución." onClose={()=>setMeasurement(null)}><div className="modal-body"><label>Fecha<input type="date" value={measurement.date} onChange={e=>setMeasurement({...measurement,date:e.target.value})}/></label><div className="two-col"><label>Peso · kg<input autoFocus type="number" inputMode="decimal" step="0.1" min="20" max="500" placeholder="Ej. 93.5" value={measurement.weight??''} onChange={e=>setMeasurement({...measurement,weight:e.target.value===''?null:Number(e.target.value)})}/></label><label>Cintura · cm<input type="number" inputMode="decimal" step="0.1" min="20" max="300" placeholder="Ej. 95" value={measurement.waist??''} onChange={e=>setMeasurement({...measurement,waist:e.target.value===''?null:Number(e.target.value)})}/></label></div><p className="helper">Puedes registrar solo uno de los dos. Un nuevo registro en la misma fecha actualiza las medidas de ese día. Procura medir en condiciones similares.</p></div><div className="modal-footer"><button className="btn secondary" onClick={()=>setMeasurement(null)}>Cancelar</button><button className="btn primary" onClick={saveMeasure}><Check size={17}/> Guardar registro</button></div></Modal>}
 {editor&&<Modal title="Editar rutina" subtitle="Deja todo preparado para tu próxima sesión." wide onClose={()=>setEditor(null)}><div className="modal-body"><label>Nombre de la rutina<input value={editor.name} onChange={e=>setEditor({...editor,name:e.target.value})}/></label><div className="editor-stack">{editor.exercises.map((e,i)=><ExerciseEditor key={e.id} exercise={e} index={i} total={editor.exercises.length} onChange={x=>setEditor({...editor,exercises:editor.exercises.map(y=>y.id===e.id?x:y)})} onRemove={()=>setEditor({...editor,exercises:editor.exercises.filter(x=>x.id!==e.id)})} onMove={dir=>setEditor(move(editor,i,dir))}/>)}</div><button className="btn secondary full" onClick={()=>setEditor({...editor,exercises:[...editor.exercises,newExercise()]})}><Plus size={17}/> Agregar ejercicio</button></div><div className="modal-footer"><button className="btn secondary" onClick={()=>setEditor(null)}>Cancelar</button><button className="btn primary" onClick={()=>{if(saveRoutine(editor)){setEditor(null);notify('Rutina guardada');}}}><Check size={17}/> Guardar rutina</button></div></Modal>}
 {importOpen&&<Modal title={parsed?'Revisa tu rutina':'Del texto al entrenamiento'} subtitle={parsed?'Puedes ajustar todos los detalles antes de guardar.':'Pega un plan con ejercicios, series y repeticiones.'} wide onClose={()=>setImportOpen(false)}><div className="modal-body">{!parsed?<><div className="import-instructions"><FileText size={22}/><p>Formato recomendado:<br/><b>Press de banca: 3 × 6–8, 100 kg, descanso 2 min</b></p></div><textarea className="import-textarea" autoFocus value={importText} onChange={e=>setImportText(e.target.value)} placeholder={'Día 1: Pecho y espalda\nPress de banca: 3 × 6–8, descanso 2 min\nRemo con barra: 3 × 8–10, descanso 90 s'}/><button className="text-btn" onClick={()=>setImportText(TEMPLATE)}><Sparkles size={15}/> Cargar ejemplo editable</button><p className="helper">Acepta varios días, «3x10» o «3 series de 10». Los datos faltantes quedarán visibles para revisión. Esta versión usa un lector de formatos, por lo que textos muy libres pueden necesitar ajustes.</p></>:<>{parsed.warnings.length>0&&<div className="import-warnings"><b>Detalles para revisar</b>{parsed.warnings.map((w,i)=><p key={i}>{w}</p>)}</div>}{parsed.routines.map((r,ri)=><div className="import-day" key={r.id}><label>Nombre de la rutina<input value={r.name} onChange={e=>setParsed({...parsed,routines:parsed.routines.map(x=>x.id===r.id?{...x,name:e.target.value}:x)})}/></label>{r.exercises.map((e,i)=><ExerciseEditor key={e.id} exercise={e} index={i} total={r.exercises.length} onChange={x=>setParsed({...parsed,routines:parsed.routines.map(y=>y.id===r.id?{...y,exercises:y.exercises.map(z=>z.id===e.id?x:z)}:y)})} onRemove={()=>setParsed({...parsed,routines:parsed.routines.map(y=>y.id===r.id?{...y,exercises:y.exercises.filter(z=>z.id!==e.id)}:y)})} onMove={dir=>setParsed({...parsed,routines:parsed.routines.map(y=>y.id===r.id?move(y,i,dir):y)})}/>)}</div>)}</>}</div><div className="modal-footer">{parsed?<><button className="btn secondary" onClick={()=>setParsed(null)}>Volver al texto</button><button className="btn primary" onClick={()=>{if(parsed.routines.some(r=>!r.name.trim()||!r.exercises.length||r.exercises.some(e=>!e.name.trim()||!e.primary.length||e.sets<1||e.sets>30||(e.weight!==null&&e.weight<0)||(e.rest!==null&&(e.rest<0||e.rest>3600))))){notify('Completa los nombres, músculos y valores de las rutinas.');return;}parsed.routines.forEach(r=>store.put('routine',r));setImportOpen(false);setParsed(null);setTab('routines');notify('Rutinas importadas. Listas para entrenar.');}}><Check size={17}/> Guardar {parsed.routines.length} {parsed.routines.length===1?'rutina':'rutinas'}</button></>:<><button className="btn secondary" onClick={()=>setImportOpen(false)}>Cancelar</button><button className="btn primary" disabled={!importText.trim()} onClick={()=>{const p=parseRoutine(importText);if(!p.routines.length){notify('No pude reconocer ejercicios. Usa el formato del ejemplo.');return;}setParsed(p);}}><Sparkles size={17}/> Convertir texto</button></>}</div></Modal>}
 {exerciseSearch!==null&&workout&&<Modal title="Agregar ejercicio" subtitle="Este cambio afecta solo a la sesión actual." onClose={()=>setExerciseSearch(null)}><div className="modal-body"><div className="search-field"><Search size={18}/><input autoFocus aria-label="Buscar ejercicio" placeholder="Busca un ejercicio…" value={exerciseSearch} onChange={e=>setExerciseSearch(e.target.value)}/></div><div className="catalog-list">{CATALOG.filter(c=>normalize(c.name).includes(normalize(exerciseSearch))).map(c=><button key={c.name} onClick={()=>{const e=newExercise(c.name);editWorkout({...workout,exercises:[...workout.exercises,{...e,sets:Array.from({length:3},()=>({id:uid(),weight:null,reps:null,done:false,warmup:false}))}]});setExerciseSearch(null);}}><span><b>{c.name}</b><small>{c.primary.join(' · ')}</small></span><Plus size={18}/></button>)}</div></div></Modal>}
 {finishOpen&&workout&&<Modal title="Una sesión más en tu historia" subtitle={`${completed} de ${total} series completadas.`} onClose={()=>setFinishOpen(false)}><div className="modal-body"><div className="finish-stats"><CheckCircle2 size={40}/><h3>{workout.name}</h3><p>{fmt(tonnage(workout))} kg de carga acumulada</p></div>{completed<total&&<p className="helper">Hay series sin completar. Quedarán guardadas como pendientes y no contarán en el volumen realizado.</p>}</div><div className="modal-footer"><button className="btn secondary" onClick={()=>setFinishOpen(false)}>Seguir entrenando</button><button className="btn primary" onClick={()=>{store.put('session',{...workout,status:'finished',endedAt:Date.now(),timerEnd:null});setFinishOpen(false);setTab('progress');setRange('week');notify('Sesión completada. Buen trabajo.');}}>Guardar sesión <Check size={17}/></button></div></Modal>}
 {exports&&<Modal title="Tus datos, contigo" subtitle="Exporta tu historial para analizarlo o migra una copia completa." onClose={()=>setExports(false)}><div className="modal-body export-options"><button onClick={exportTraining}><span className="export-icon"><Dumbbell size={23}/></span><span><b>Entrenamientos · CSV</b><small>Series, kilos, reps, músculos y descansos.</small></span><ArrowDownToLine size={19}/></button><button onClick={exportMeasures}><span className="export-icon"><Ruler size={23}/></span><span><b>Medidas · CSV</b><small>Todos los registros de peso y cintura.</small></span><ArrowDownToLine size={19}/></button><button onClick={exportVolume}><span className="export-icon"><Layers size={23}/></span><span><b>Volumen muscular · CSV</b><small>Período seleccionado en Progreso / Volumen.</small></span><ArrowDownToLine size={19}/></button><button onClick={()=>{setExports(false);setSummaryOpen(true);}}><span className="export-icon"><FileText size={23}/></span><span><b>Resumen para ChatGPT</b><small>Medidas, sesiones y volumen del período.</small></span><ArrowUpRight size={19}/></button><button onClick={()=>download('fit-z-respaldo-'+today()+'.json',JSON.stringify({app:'fit-z',version:1,exportedAt:new Date().toISOString(),records:store.records},null,2),'application/json')}><span className="export-icon"><Cloud size={23}/></span><span><b>Copia completa · JSON</b><small>Rutinas, medidas, sesiones y entrenamiento en curso.</small></span><ArrowDownToLine size={19}/></button><label className="export-upload"><span className="export-icon"><RotateCcw size={23}/></span><span><b>Restaurar copia · JSON</b><small>Importa un respaldo de Fit Z y sincronízalo con esta instalación.</small></span><ArrowUpRight size={19}/><input type="file" accept="application/json,.json" onChange={e=>{const file=e.target.files?.[0];if(file)void restoreBackup(file);e.currentTarget.value='';}}/></label></div></Modal>}
 {summaryOpen&&<Modal title="Resumen para analizar" subtitle="Copia este texto y pégalo en nuestra conversación." wide onClose={()=>setSummaryOpen(false)}><div className="modal-body"><textarea className="summary-text" readOnly value={summary}/></div><div className="modal-footer"><button className="btn secondary" onClick={()=>download('fit-z-resumen-'+today()+'.txt',summary)}>Descargar TXT</button><button className="btn primary" onClick={async()=>{try{await navigator.clipboard.writeText(summary);notify('Resumen copiado');}catch{notify('Selecciona y copia el texto del resumen.');}}}><Copy size={17}/> Copiar resumen</button></div></Modal>}
 {Object.keys(store.conflicts).length>0&&<Modal title="Hay dos versiones de un registro" subtitle="Se modificó en otro dispositivo. Elige cuál conservar." onClose={()=>notify('Elige una versión para continuar la sincronización.')}><div className="modal-body">{Object.entries(store.conflicts).map(([id,r])=>{const local=store.records.find(x=>x.id===id);return <div className="conflict" key={id}><h3>{'name' in r.body?r.body.name:('date' in r.body?r.body.date:'Registro')}</h3><details><summary>Comparar versiones</summary><div className="two-col"><div><b>Este dispositivo</b><pre>{JSON.stringify(local?.body,null,2)}</pre></div><div><b>Otro dispositivo</b><pre>{JSON.stringify(r.body,null,2)}</pre></div></div></details><div className="heading-buttons"><button className="btn secondary" onClick={()=>store.resolve(id,false)}>Usar la otra versión</button><button className="btn primary" onClick={()=>store.resolve(id,true)}>Conservar esta versión</button></div></div>;})}</div></Modal>}
 </div>;
}
